#include <stdint.h>
#include <stdio.h>
#include "stm32f446xx.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning __"FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."__
#endif

void SysTickDelayMS(int delay){

    SysTick->VAL = 0;
    SysTick->LOAD = 15999;
    SysTick->CTRL = (1U) | (1U << 2);
    while(delay){
        while(!(SysTick->CTRL & (1U << 16))){}
        delay--;
    }
    SysTick->CTRL = 0;
}

int main(void)
{
    RCC->AHB1ENR |= (1U << 0);
    GPIOA->MODER |= (1U << 10);
    GPIOA->MODER &= ~(1U << 11);

    while(1){
        GPIOA->ODR ^= (1U << 5);
        SysTickDelayMS(500);
    }
}

